'use strict';
(()=>{
 const header=document.querySelector('.sidebar'),nav=header?.querySelector('nav');
 if(nav){
  const menu=document.createElement('button');menu.className='site-menu';menu.type='button';menu.innerHTML='<span aria-hidden="true">☰</span> Menu';menu.setAttribute('aria-haspopup','dialog');menu.setAttribute('aria-controls','site-drawer');menu.setAttribute('aria-expanded','false');header.append(menu);
  const dialog=document.createElement('dialog');dialog.id='site-drawer';dialog.className='site-drawer';dialog.setAttribute('aria-label','Site navigation');dialog.innerHTML='<div class="drawer-heading"><span>Liberty Watch</span><button type="button" class="drawer-close" aria-label="Close navigation">×</button></div><p class="eyebrow">YOUR LEGISLATIVE DESK</p>';nav.before(document.createComment('Navigation is moved into the accessible menu by site-ui.js.'));dialog.append(nav);document.body.append(dialog);document.body.classList.add('drawer-ready');
  const close=()=>{dialog.close();menu.setAttribute('aria-expanded','false');document.body.classList.remove('drawer-open');menu.focus();};menu.addEventListener('click',()=>{dialog.showModal();menu.setAttribute('aria-expanded','true');document.body.classList.add('drawer-open');});dialog.querySelector('.drawer-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}else if(e.target.closest('.nav-item'))close();});
 }
 const main=document.querySelector('main');if(!main)return;
 const helper=document.createElement('form');helper.className='search simple-search cross-fallback';helper.setAttribute('role','search');helper.innerHTML='<label class="sr-only" for="site-search-input">Search all Liberty Watch</label><input id="site-search-input" type="search" placeholder="Search all Liberty Watch" autocomplete="off"><button type="submit" aria-label="Search all Liberty Watch">⌕</button>';main.querySelector('.wire-intro,.intro,.news-hero,.voices-intro,.guest-article header')?.after(helper);
 const panel=document.createElement('section');panel.className='cross-results';panel.hidden=true;panel.setAttribute('aria-label','Site-wide search results');
 let active=null,rows=null,loadPromise=null,failures=[],revision=0,limit=8;
 function context(){if(location.pathname==='/'&&!location.hash)return 'news';if(location.pathname.includes('/news'))return 'news';if(location.pathname.includes('/rulings'))return 'rulings';if(location.pathname.includes('/hearings'))return 'hearings';return ['','#tracker','#watchlist','#activity'].includes(location.hash)&&['/','/90r/'].includes(location.pathname)?'bills':'pages';}
 function field(){return [...document.querySelectorAll('#search,#news-search,#ruling-search,#hearing-search')].find(el=>el.getClientRects().length)||helper.querySelector('input');}
 function setup(){const next=field();helper.hidden=next.id!=='site-search-input';if(active!==next){active=next;revision++;panel.hidden=true;document.body.classList.remove('cross-searching');}active.placeholder='Search all Liberty Watch';active.setAttribute('aria-label','Search all Liberty Watch');const form=active.closest('form')||active.parentElement;form.querySelector('button[type=submit],button')?.setAttribute('aria-label','Search all Liberty Watch');let note=form.nextElementSibling;if(!note?.classList.contains('cross-help')){note=document.createElement('p');note.className='cross-help';form.after(note);}note.textContent=`Search bills, rulings, hearings and news. ${LibertySearch.labels[context()]} first.`;note.after(panel);}
 async function load(){if(!loadPromise)loadPromise=Promise.allSettled(['bills','rulings','hearings','news','pages'].map(async name=>{const response=await fetch('/data/'+name+'.json');if(!response.ok)throw Error(name);return [name,await response.json()];})).then(results=>{const data={};failures=[];results.forEach((r,i)=>r.status==='fulfilled'?data[r.value[0]]=r.value[1]:failures.push(['Bills','Court rulings','Hearings','News','Site pages'][i]));rows=LibertySearch.records(data);});await loadPromise;}
 const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n;};
 function highlight(node,text,query){const tokens=LibertySearch.normalize(query).split(' ').filter(t=>t.length>1);if(!tokens.length){node.textContent=text;return;}const rx=new RegExp('('+tokens.join('|')+')','ig');String(text).split(rx).forEach((part,i)=>node.append(i%2?el('mark','',part):document.createTextNode(part)));}
 async function run(){const q=active.value.trim(),version=++revision;limit=8;panel.hidden=!q;document.body.classList.toggle('cross-searching',Boolean(q));if(!q)return;panel.replaceChildren(el('p','','Searching Liberty Watch…'));await load();if(version!==revision)return;draw(q);}
 function draw(q){const hits=LibertySearch.search(rows,q,context());panel.replaceChildren();const status=el('p','cross-status',`${hits.length} site-wide result${hits.length===1?'':'s'}. ${LibertySearch.labels[context()]} first.`);status.setAttribute('role','status');panel.append(status);panel.append(el('p','cross-note','These results search all sections, including retained records. Clear the search to return to section filters.'));
  if(failures.length){panel.append(el('p','notice','Some sections could not load: '+failures.join(', ')+'. Results below may be incomplete.'));const retry=el('button','button','Retry unavailable sections');retry.type='button';retry.onclick=()=>{loadPromise=null;run();};panel.append(retry);}
  if(!hits.length)panel.append(el('p','','No site-wide matches. Try a bill number, case name, author, or shorter topic.'));
  const types=[context(),...Object.keys(LibertySearch.labels).filter(t=>t!==context())];for(const type of types){const matches=hits.filter(r=>r.type===type);if(!matches.length)continue;const group=el('section','cross-group');group.append(el('h2','',LibertySearch.labels[type]+' · '+matches.length));for(const r of matches.slice(0,limit)){const article=el('article','cross-result'),heading=el('h3'),link=el('a');let url;try{url=new URL(r.url,location.origin);}catch{continue;}if(!['http:','https:'].includes(url.protocol))continue;link.href=url.href;if(url.origin!==location.origin){link.target='_blank';link.rel='noopener';}highlight(link,r.title,q);heading.append(link);article.append(heading,el('p','cross-meta',r.meta));if(r.description&&r.description!==r.title){const desc=el('p','cross-excerpt');const text=String(r.description);const term=LibertySearch.normalize(q).split(' ').find(t=>text.toLowerCase().includes(t));const at=term?text.toLowerCase().indexOf(term):0;const start=Math.max(0,at-70);highlight(desc,(start?'…':'')+text.slice(start,start+310)+(text.length>start+310?'…':''),q);article.append(desc);}group.append(article);}panel.append(group);}
  if(types.some(t=>hits.filter(r=>r.type===t).length>limit)){const more=el('button','button','Show more results');more.type='button';more.onclick=()=>{limit+=15;draw(q);};panel.append(more);}
 }
 document.addEventListener('input',e=>{if(e.target===active)run();});document.addEventListener('submit',e=>{if(e.target.contains(active)){e.preventDefault();run();}});document.addEventListener('click',e=>{if(e.target.closest('#clear-filters,#ruling-reset'))setTimeout(()=>{setup();run();},0);});document.addEventListener('liberty-view-change',()=>{setup();run();});window.addEventListener('hashchange',()=>setTimeout(()=>{setup();run();},0));document.addEventListener('click',e=>{if(e.target.closest('[data-view]'))setTimeout(()=>{setup();run();},0);});setup();
})();
